SELECT COUNT(DISTINCT "MulheresMil_1"."Calculation_838513981462429699") AS "ctd_Calculation_838513981462429699_ok" FROM "MulheresMil_1" WHERE (("MulheresMil_1"."eixo_tecnologico_catalogo_guia" IN ('Hospitalidade e Lazer', 'Turismo, Hospitalidade e Lazer')) AND ("MulheresMil_1"."eixo_tecnologico" = 'Turismo, Hospitalidade e Lazer') AND (NOT (("MulheresMil_1"."nome_da_sit_matricula__situacao_detalhada_" IN ('CANC_DESISTENTE', 'CANC_MAT_PRIM_OPCAO', 'CANC_SANÇÃO', 'CANC_SEM_FREQ_INICIAL', 'CANC_TURMA', 'DOC_INSUFIC', 'ESCOL_INSUFIC', 'INC _ITINERARIO', 'INSC_CANC', 'Não Matriculado', 'NÃO_COMPARECEU', 'TURMA_CANC', 'VAGAS_INSUFIC')) OR ("MulheresMil_1"."nome_da_sit_matricula__situacao_detalhada_" IS NULL))) AND (NOT ("MulheresMil_1"."situacao_da_turma" IN ('CANCELADA', 'CRIADA', 'PUBLICADA')))) HAVING (COUNT(1) > 0);
